parameters.jsCode:
// Shopify has no "price changed" webhook topic, so this polls the product
// list and diffs every variant price against a snapshot kept in workflow
// static data. The FIRST run records the baseline and announces nothing -
// that is the correct outcome, not a failure: there is nothing to compare
// against yet. From the second run on, the biggest qualifying drop wins.
const cfg = $('Config').first().json;
const res = $input.first().json;
const status = Number(res.statusCode);

if (!Number.isFinite(status) || status === 0) {
  throw new Error('Could not reach ' + (cfg.shopDomain || '(shopDomain is empty)') + '. shopDomain looks like "your-store.myshopify.com", and the shopify-token credential must be attached to Poll price drops.');
}
if (status === 401 || status === 403) {
  throw new Error('Shopify rejected the token (HTTP ' + status + '). The custom app needs the read_products scope and the header name must be X-Shopify-Access-Token.');
}
if (status !== 200) {
  throw new Error('Shopify answered HTTP ' + status + ': ' + JSON.stringify(res.body).slice(0, 300));
}

let body = res.body;
if (typeof body === 'string') {
  try { body = JSON.parse(body); } catch (e) {
    throw new Error('Shopify answered 200 but the body was not JSON.');
  }
}
const products = Array.isArray(body.products) ? body.products : [];

const store = $getWorkflowStaticData('global');
if (!store.priceSnapshot || typeof store.priceSnapshot !== 'object') store.priceSnapshot = {};
const snapshot = store.priceSnapshot;
const minDrop = Number(cfg.minDropPercent) > 0 ? Number(cfg.minDropPercent) : 5;

let best = null;
let seen = 0;
let baseline = 0;
for (const p of products) {
  const variants = Array.isArray(p.variants) ? p.variants : [];
  for (const v of variants) {
    const key = String(v.id);
    const price = parseFloat(v.price);
    if (!Number.isFinite(price)) continue;
    seen += 1;
    const was = Number(snapshot[key]);
    snapshot[key] = price;
    if (!Number.isFinite(was)) { baseline += 1; continue; }
    if (!(price < was)) continue;
    const pct = ((was - price) / was) * 100;
    if (pct < minDrop) continue;
    if (!best || pct > best.pct) best = { pct, was, price, product: p, variant: v };
  }
}

if (!best) {
  return [{ json: {
    found: false,
    reason: seen === 0
      ? 'No product variants came back from Shopify.'
      : (baseline === seen
        ? 'Baseline recorded for ' + seen + ' variants. The next poll compares against it - price drops are announced from then on.'
        : 'No price drop of at least ' + minDrop + '% since the last poll (' + seen + ' variants checked).'),
    checked: seen,
  } }];
}

const image = best.product.image && best.product.image.src ? best.product.image.src : '';
if (!image) {
  throw new Error('"' + best.product.title + '" dropped in price but has no product image in Shopify. Add one, or announce this sale from the sheet instead.');
}
const symbol = String(cfg.currencySymbol || '$');
const fmt = (n) => symbol + (Math.abs(n - Math.round(n)) < 0.005 ? String(Math.round(n)) : n.toFixed(2));

return [{ json: {
  found: true,
  product: String(best.product.title || '').trim(),
  oldPrice: fmt(best.was),
  newPrice: fmt(best.price),
  imageUrl: image,
  endsAt: String(cfg.defaultEndsAt || '').trim(),
  rowNumber: null,
  sourceKind: 'shopify',
  variantId: String(best.variant.id),
  productHandle: String(best.product.handle || ''),
  checked: seen,
} }];

// The Google Sheets node emits one item per row plus a row_number field.
// Keep the FIRST row whose Status column is empty - row_number lets the
// update node at the end mark exactly that row as done.
const rows = $input.all().map((i) => i.json);
const isEmpty = (v) => v === undefined || v === null || String(v).trim() === '';
const row = rows.find((r) => isEmpty(r.Status));

if (!row) {
  return [{ json: {
    found: false,
    reason: 'Every row in the sale sheet already has a Status. Add a new price-drop row to announce.',
    checked: rows.length,
  } }];
}

const need = ['Product', 'OldPrice', 'NewPrice', 'ImageUrl'];
const missing = need.filter((k) => isEmpty(row[k]));
if (missing.length) {
  throw new Error('Row ' + row.row_number + ' is missing ' + missing.join(', ') + '. Fill those columns, or put anything in Status to skip the row.');
}

return [{ json: {
  found: true,
  product: String(row.Product).trim(),
  oldPrice: String(row.OldPrice).trim(),
  newPrice: String(row.NewPrice).trim(),
  imageUrl: String(row.ImageUrl).trim(),
  endsAt: isEmpty(row.EndsAt) ? '' : String(row.EndsAt).trim(),
  rowNumber: row.row_number,
  sourceKind: 'sheet',
  checked: rows.length,
} }];

// Nothing pending in the sheet, or no qualifying price drop since the last
// poll. A normal, successful outcome - not an error.
let picked = null;
try { picked = $('Pick next sale').first().json; } catch (e) { /* sheet branch did not run */ }
if (!picked) picked = $('Find price drops').first().json;
return [{ json: {
  rendered: false,
  reason: picked.reason || 'Nothing to announce right now.',
  checked: picked.checked,
  source: $('Config').first().json.source,
} }];

// The plan caps audio assets at ~5 MB, and a dead music URL would fail the
// whole render. HEAD the file first: unreachable or oversized means the sale
// video renders WITHOUT music instead of not rendering at all.
const cfg = $('Config').first().json;
const res = $input.first().json;

let sale = null;
try { sale = $('Pick next sale').first().json; } catch (e) { /* sheet branch did not run */ }
if (!sale || !sale.found) sale = $('Find price drops').first().json;

const max = Number(cfg.maxMusicBytes) > 0 ? Number(cfg.maxMusicBytes) : 5242880;
const url = String(cfg.musicUrl || '').trim();
let musicUrl = '';
let musicNote = 'no musicUrl in Config - rendering without a music bed';

if (url) {
  const status = Number(res.statusCode);
  const headers = res.headers || {};
  const len = Number(headers['content-length'] || headers['Content-Length'] || 0);
  if (!Number.isFinite(status) || status === 0) {
    musicNote = 'the music URL was unreachable - rendering without a music bed';
  } else if (status >= 400) {
    musicNote = 'the music URL answered HTTP ' + status + ' - rendering without a music bed';
  } else if (len > max) {
    musicNote = 'the music file is ' + len + ' bytes, over the ' + max + ' byte cap - rendering without a music bed';
  } else {
    musicUrl = url;
    musicNote = len > 0 ? 'music bed OK (' + len + ' bytes)' : 'music bed OK (the server did not report a size)';
  }
}

return [{ json: { ...sale, musicUrl, musicNote } }];

// Builds BOTH deliverables for one price drop:
//   item 1 -> a 1080x1920 flash-sale video for socials
//   item 2 -> a still image banner (type: "image") for the email blast
// Same render API, same credentials; only the payload differs.
//
// Design adapted from Zvid's library: ecom-flash-sale (angled urgency bands,
// Anton headline, struck-through price beat), ecom-launch-countdown (radial
// glow + ring composition on the deal scene) and img-ecom-flash-sale (the
// banner's left-copy / right-product split with the promo chip).

// --- small helpers ---------------------------------------------------------
function escapeHtml(s) {
  return String(s == null ? '' : s).replace(/[&<>"']/g, (c) => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
  }[c]));
}

function clean(v) {
  return String(v == null ? '' : v).replace(/\s+/g, ' ').trim();
}

function round2(n) {
  return Math.round(n * 100) / 100;
}

// The render API's project-name pattern is strict ASCII: /^[a-zA-Z0-9_\- ]+$/.
// Product titles are routinely not, so slug hard and keep a fallback.
function sanitizeProjectName(s) {
  const out = String(s).toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 90);
  return out || 'flash-sale';
}

function hexRgb(hex) {
  const m = /^#?([0-9a-fA-F]{6})$/.exec(String(hex).trim());
  if (!m) return '255,255,255';
  const n = parseInt(m[1], 16);
  return ((n >> 16) & 255) + ',' + ((n >> 8) & 255) + ',' + (n & 255);
}

// "$1,299.99" -> { amount: 1299.99, symbol: '$', display: '$1,299.99' }
// Bare numbers ("129") inherit the currency symbol from the other price, or
// fall back to the configured one, so a sheet can be sloppy about formatting.
// `typed` records whether the sheet actually spelled a symbol: if it did, that
// exact string goes on screen; if it did not, the number is reformatted with
// the currency symbol rather than shown bare (a sale creative reading
// "129 -> 89" next to a "$40" savings chip looks broken).
function parsePrice(raw, fallbackSymbol) {
  const text = clean(raw);
  const symbolMatch = /[^\d\s.,\-]+/.exec(text);
  const symbol = symbolMatch ? symbolMatch[0] : (fallbackSymbol || '');
  const numeric = text.replace(/[^\d.,-]/g, '').replace(/,/g, '');
  const amount = Number.parseFloat(numeric);
  return {
    amount: Number.isFinite(amount) ? amount : null,
    symbol,
    typed: Boolean(symbolMatch),
    display: text,
    raw: text,
  };
}

function groupThousands(intPart) {
  return String(intPart).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
}

// Whole amounts print without decimals ($52), fractional amounts keep two
// ($52.50) — the way a storefront prints them.
function formatMoney(amount, symbol) {
  const abs = Math.abs(amount);
  const whole = Math.abs(abs - Math.round(abs)) < 0.005;
  const fixed = whole ? String(Math.round(abs)) : abs.toFixed(2);
  const parts = fixed.split('.');
  return (symbol || '') + groupThousands(parts[0]) + (parts[1] ? '.' + parts[1] : '');
}

// Largest size from the ramp whose estimated wrap stays inside maxLines.
// avgEm is the average glyph width in em for the face (Anton is narrow,
// Space Grotesk is wider). Errs towards "one size smaller" so nothing clips.
function fitSize(text, sizes, boxWidth, maxLines, avgEm) {
  const words = String(text).split(/\s+/).filter(Boolean);
  const longest = Math.max.apply(null, words.map((w) => w.length).concat([1]));
  let last = sizes[sizes.length - 1];
  for (let i = 0; i < sizes.length; i++) {
    const size = sizes[i];
    const per = Math.max(4, Math.floor(boxWidth / (size * avgEm)));
    let lines = 1;
    let used = 0;
    for (let j = 0; j < words.length; j++) {
      const w = words[j];
      const need = used === 0 ? w.length : used + 1 + w.length;
      if (need <= per) { used = need; continue; }
      lines += 1;
      used = Math.min(w.length, per);
    }
    last = size;
    if (lines <= maxLines && longest * size * avgEm <= boxWidth) return { size: size, lines: lines };
  }
  const per = Math.max(4, Math.floor(boxWidth / (last * avgEm)));
  let lines = 1;
  let used = 0;
  for (let j = 0; j < words.length; j++) {
    const w = words[j];
    const need = used === 0 ? w.length : used + 1 + w.length;
    if (need <= per) { used = need; continue; }
    lines += 1;
    used = Math.min(w.length, per);
  }
  return { size: last, lines: lines };
}

// Width of a single-line run, in px. avgEm is the average glyph advance for
// the face/case (Space Grotesk bold reads ~0.62em uppercase, ~0.56em mixed).
// SVG <text> does not wrap or shrink, so every pill below is sized from this.
function runWidth(text, fontPx, letterSpacing, avgEm) {
  const n = String(text).length;
  return Math.ceil(n * (fontPx * avgEm + letterSpacing));
}

// Largest font from `sizes` whose single line fits `maxWidth`; falls back to
// the smallest and truncates with an ellipsis so a pill can never spill.
function fitRun(text, sizes, maxWidth, letterSpacing, avgEm) {
  const s = String(text);
  for (let i = 0; i < sizes.length; i++) {
    if (runWidth(s, sizes[i], letterSpacing, avgEm) <= maxWidth) {
      return { text: s, size: sizes[i], width: runWidth(s, sizes[i], letterSpacing, avgEm) };
    }
  }
  const size = sizes[sizes.length - 1];
  const per = Math.max(1, Math.floor(maxWidth / (size * avgEm + letterSpacing)));
  const cut = s.slice(0, Math.max(1, per - 3)).replace(/\s+$/, '') + '...';
  return { text: cut, size: size, width: runWidth(cut, size, letterSpacing, avgEm) };
}

// --- the build -------------------------------------------------------------
function buildFlashSale(cfg, sale) {
  const ink = clean(cfg.inkColor) || '#0D0D0D';
  const urgency = clean(cfg.urgencyAccent) || '#E11D2E';
  const accent = clean(cfg.brandAccent) || '#FFD54A';
  const textColor = clean(cfg.textColor) || '#FFFFFF';
  const muted = clean(cfg.mutedColor) || '#9CA3AF';
  const displayFont = clean(cfg.displayFont) || 'Anton';
  const uiFont = clean(cfg.uiFont) || 'Space Grotesk';
  const inkRgb = hexRgb(ink);
  const accentRgb = hexRgb(accent);
  const urgencyRgb = hexRgb(urgency);

  const brandName = clean(cfg.brandName) || 'Your Store';
  const storeUrl = clean(cfg.storeUrl).replace(/^https?:\/\//i, '').replace(/\/+$/, '');
  const ctaText = clean(cfg.ctaText) || 'Shop the sale';
  const promoCode = clean(cfg.promoCode);

  const product = clean(sale.product);
  if (!product) throw new Error('The sale has no product name.');
  const imageUrl = clean(sale.imageUrl);
  if (!imageUrl) throw new Error('The sale for "' + product + '" has no ImageUrl. A flash-sale creative needs a product photo.');

  const oldPrice = parsePrice(sale.oldPrice, clean(cfg.currencySymbol) || '$');
  const newPrice = parsePrice(sale.newPrice, oldPrice.symbol || clean(cfg.currencySymbol) || '$');
  if (oldPrice.amount === null || newPrice.amount === null) {
    throw new Error('Could not read the prices for "' + product + '" (OldPrice "' + oldPrice.raw + '", NewPrice "' + newPrice.raw + '"). Use plain numbers like 129 or 129.00, with or without a currency symbol.');
  }
  // A typo'd cell ("-5", "0") would otherwise sail past the "is this really a
  // drop?" check below and publish a >=100% discount, with formatMoney hiding
  // the minus sign. Both prices must be real, positive money first.
  if (!(oldPrice.amount > 0) || !(newPrice.amount > 0)) {
    throw new Error('Both prices for "' + product + '" must be above zero (OldPrice "' + oldPrice.raw + '", NewPrice "' + newPrice.raw + '").');
  }
  if (!(newPrice.amount < oldPrice.amount)) {
    throw new Error('"' + product + '" is not a price drop: NewPrice (' + newPrice.raw + ') must be lower than OldPrice (' + oldPrice.raw + ').');
  }
  const symbol = newPrice.symbol || oldPrice.symbol || '$';
  const oldDisplay = oldPrice.typed ? oldPrice.display : formatMoney(oldPrice.amount, symbol);
  const newDisplay = newPrice.typed ? newPrice.display : formatMoney(newPrice.amount, symbol);
  const savedAmount = round2(oldPrice.amount - newPrice.amount);
  const savedDisplay = formatMoney(savedAmount, symbol);
  // FLOOR, never round: rounding is the one direction that overstates the offer
  // to a shopper (49.86% off would go on screen as "50% OFF").
  const exactPct = ((oldPrice.amount - newPrice.amount) / oldPrice.amount) * 100;
  const discountPct = Math.floor(exactPct);
  if (discountPct < 1) {
    throw new Error('"' + product + '" is only a ' + round2(exactPct) + '% drop - under 1%, too small to announce as a flash sale.');
  }

  const endsAt = clean(sale.endsAt);
  const endsLine = endsAt ? ('ENDS ' + endsAt).toUpperCase() : '';

  const musicUrl = clean(sale.musicUrl);
  const musicVolume = Number(cfg.musicVolume);

  // ---------------------------------------------------------------- video --
  const tDur = 0.45;
  const s1Content = 3.2;
  const s2Content = 5.8;
  const s3Content = 4.4;
  const s1 = round2(s1Content + tDur);
  const s2 = round2(s2Content + tDur);
  const s3 = s3Content;
  const totalSeconds = round2(s1 + s2 + s3 - tDur * 2);

  const bandsSvg =
    "<svg width='1080' height='1920' viewBox='0 0 1080 1920' xmlns='http://www.w3.org/2000/svg'>" +
    "<defs><radialGradient id='fsHook' cx='0.5' cy='0.42' r='0.85'>" +
    "<stop offset='0' stop-color='#FFFFFF' stop-opacity='0.16'/><stop offset='1' stop-color='#FFFFFF' stop-opacity='0'/>" +
    "</radialGradient><linearGradient id='fsHookFloor' x1='0' y1='0' x2='0' y2='1'>" +
    "<stop offset='0.72' stop-color='" + ink + "' stop-opacity='0'/><stop offset='1' stop-color='" + ink + "' stop-opacity='0.4'/>" +
    '</linearGradient></defs>' +
    "<rect width='1080' height='1920' fill='" + urgency + "'/>" +
    "<rect width='1080' height='1920' fill='url(#fsHook)'/>" +
    "<path d='M-200 392 L1280 320 L1280 720 L-200 792 Z' fill='" + ink + "' opacity='0.17'/>" +
    "<path d='M-200 380 L1280 308 L1280 326 L-200 398 Z' fill='" + accent + "' opacity='0.92'/>" +
    "<path d='M-200 792 L1280 720 L1280 738 L-200 810 Z' fill='" + accent + "' opacity='0.92'/>" +
    "<rect width='1080' height='1920' fill='url(#fsHookFloor)'/>" +
    '</svg>';

  const heroPanelSvg =
    "<svg width='680' height='830' viewBox='0 0 680 830' xmlns='http://www.w3.org/2000/svg'>" +
    "<rect x='2' y='2' width='676' height='826' rx='44' fill='rgba(" + inkRgb + ",0.26)' stroke='rgba(255,255,255,0.55)' stroke-width='3'/>" +
    "<rect x='20' y='20' width='640' height='790' rx='30' fill='none' stroke='rgba(255,255,255,0.2)' stroke-width='1.5'/>" +
    '</svg>';

  const burstSvg = (pct) =>
    "<svg width='280' height='280' viewBox='0 0 280 280' xmlns='http://www.w3.org/2000/svg'>" +
    "<circle cx='140' cy='140' r='134' fill='rgba(" + inkRgb + ",0.35)'/>" +
    "<circle cx='140' cy='140' r='118' fill='" + accent + "'/>" +
    "<circle cx='140' cy='140' r='106' fill='none' stroke='rgba(" + inkRgb + ",0.35)' stroke-width='2' stroke-dasharray='7 9'/>" +
    "<text x='140' y='150' font-family='Anton, Impact, Arial' font-size='" + (String(pct).length > 2 ? 66 : 76) + "' fill='" + ink + "' text-anchor='middle' letter-spacing='-2'>-" + pct + "%</text>" +
    "<text x='140' y='196' font-family='Space Grotesk, Arial' font-size='24' font-weight='700' fill='" + ink + "' text-anchor='middle' letter-spacing='8'>OFF</text>" +
    '</svg>';

  // A slow diagonal light sweep keeps the hook scene alive without competing
  // with the type. One loop = the whole scene, per the customCode contract.
  const sweep = (seconds) => ({
    animationDuration: Math.min(15, seconds),
    css:
      '.sw{position:relative;width:1080px;height:1920px;overflow:hidden}' +
      '.sw i{position:absolute;top:-500px;left:-900px;display:block;width:420px;height:3000px;' +
      'background:linear-gradient(90deg,rgba(255,255,255,0) 0%,rgba(255,255,255,0.16) 50%,rgba(255,255,255,0) 100%);' +
      'transform:rotate(18deg);animation:swp 3.6s ease-in-out infinite}' +
      '.sw i:nth-child(2){animation-delay:-1.8s;width:220px;opacity:0.7}' +
      '@keyframes swp{0%{transform:translateX(0) rotate(18deg)}100%{transform:translateX(2400px) rotate(18deg)}}',
  });

  const productFit1 = fitSize(product, [56, 48, 42, 36, 32], 900, 2, 0.53);
  const brandChipFit = fitRun(brandName.toUpperCase(), [26, 23, 20, 18], 880, 7, 0.62);
  const ctaFit = fitRun(ctaText, [44, 39, 34, 30], 820, 0, 0.56);
  const scene1 = {
    id: 'hook',
    duration: s1,
    backgroundColor: urgency,
    transition: 'slideup',
    transitionId: 'drop',
    transitionDuration: tDur,
    visuals: [
      { type: 'SVG', width: 1080, height: 1920, track: 0, enterBegin: 0, exitEnd: s1, svg: bandsSvg },
      {
        type: 'TEXT', x: 540, y: 960, anchor: 'center-center', track: 1, opacity: 0.85,
        enterBegin: 0, exitEnd: s1,
        style: { fontFamily: uiFont, color: textColor },
        html: "<div class='sw'><i></i><i></i></div>",
        customCode: sweep(s1),
      },
      {
        type: 'TEXT', x: 540, y: 132, anchor: 'top-center', track: 2,
        enterBegin: 0.1, enterEnd: 0.5, enterAnimation: 'fade', exitEnd: s1,
        style: { fontFamily: uiFont, color: textColor },
        html: "<div style='display:inline-block; border:2px solid rgba(255,255,255,0.6); color:" + textColor + "; border-radius:999px; padding:14px 40px; font-size:" + brandChipFit.size + "px; font-weight:800; letter-spacing:7px;'>" + escapeHtml(brandChipFit.text) + '</div>',
      },
      {
        type: 'TEXT', x: 540, y: 430, width: 1000, anchor: 'top-center', track: 3,
        enterBegin: 0.15, enterEnd: 0.6, enterAnimation: 'circleopen', exitEnd: s1,
        style: { fontFamily: displayFont, color: textColor },
        html: "<div style='text-align:center; color:" + textColor + "; font-size:150px; line-height:0.92; letter-spacing:1px;'>FLASH<br><span style='color:" + accent + ";'>SALE</span></div>",
      },
      {
        type: 'SVG', x: 540, y: 1180, width: 680, height: 830, anchor: 'center-center', track: 4,
        enterBegin: 0.35, enterEnd: 0.85, enterAnimation: 'smoothup', exitEnd: s1,
        svg: heroPanelSvg,
      },
      {
        type: 'IMAGE', src: imageUrl, x: 540, y: 1180, width: 600, height: 750, anchor: 'center-center',
        radius: { tl: 30, tr: 30, bl: 30, br: 30 }, track: 5,
        enterBegin: 0.45, enterEnd: 0.95, enterAnimation: 'smoothup', exitEnd: s1,
      },
      {
        type: 'SVG', x: 846, y: 866, width: 280, height: 280, anchor: 'center-center', track: 6,
        enterBegin: 0.95, enterEnd: 1.35, enterAnimation: 'circleopen', exitEnd: s1,
        svg: burstSvg(discountPct),
      },
      {
        type: 'TEXT', x: 540, y: 1660, width: 900, anchor: 'top-center', track: 7,
        enterBegin: 1.25, enterEnd: 1.7, enterAnimation: 'smoothup', exitEnd: s1,
        style: { fontFamily: uiFont, color: textColor },
        html: "<div style='text-align:center; color:" + textColor + '; font-size:' + productFit1.size + "px; line-height:1.2; font-weight:700; letter-spacing:-0.5px;'>" + escapeHtml(product) + '</div>',
      },
    ],
  };

  const dropBgSvg =
    "<svg width='1080' height='1920' viewBox='0 0 1080 1920' xmlns='http://www.w3.org/2000/svg'>" +
    "<defs><radialGradient id='fsDrop' cx='0.5' cy='0.26' r='0.85'>" +
    "<stop offset='0' stop-color='" + urgency + "' stop-opacity='0.38'/><stop offset='1' stop-color='" + urgency + "' stop-opacity='0'/>" +
    "</radialGradient><linearGradient id='fsDropFloor' x1='0' y1='0' x2='0' y2='1'>" +
    "<stop offset='0.55' stop-color='" + ink + "' stop-opacity='0'/><stop offset='1' stop-color='" + ink + "' stop-opacity='0.85'/>" +
    '</linearGradient></defs>' +
    "<rect width='1080' height='1920' fill='" + ink + "'/>" +
    "<rect width='1080' height='1920' fill='url(#fsDrop)'/>" +
    "<rect width='1080' height='1920' fill='url(#fsDropFloor)'/>" +
    "<circle cx='540' cy='530' r='240' fill='none' stroke='rgba(" + accentRgb + ",0.24)' stroke-width='2'/>" +
    "<circle cx='540' cy='530' r='276' fill='none' stroke='rgba(" + accentRgb + ",0.11)' stroke-width='1.5'/>" +
    "<path d='M0 74 L1080 74' stroke='" + urgency + "' stroke-width='40'/>" +
    "<path d='M0 1846 L1080 1846' stroke='" + urgency + "' stroke-width='40'/>" +
    '</svg>';

  const productFit2 = fitSize(product, [50, 44, 38, 34, 30], 900, 2, 0.53);
  const newLen = newDisplay.length;
  const newSize = newLen <= 4 ? 184 : newLen <= 6 ? 156 : newLen <= 8 ? 128 : 108;
