    product: product,
    oldPrice: oldDisplay,
    newPrice: newDisplay,
    savedDisplay: savedDisplay,
    discountPct: discountPct,
    endsAt: endsAt || null,
    imageUrl: imageUrl,
    musicUrl: musicUrl || null,
    musicNote: clean(sale.musicNote) || null,
    promoCode: promoCode || null,
    brandName: brandName,
    storeUrl: storeUrl || null,
    ctaText: ctaText,
    videoSeconds: totalSeconds,
    bannerSize: bw + 'x' + bh,
    productSizeScene1: productFit1.size,
    productSizeScene2: productFit2.size,
    newPriceSize: newSize,
    rowNumber: sale.rowNumber == null ? null : sale.rowNumber,
    sourceKind: clean(sale.sourceKind) || 'sheet',
    videoName: slug,
  };

  return { videoPayload: videoPayload, bannerPayload: bannerPayload, meta: meta };
}

// === n8n glue ===
const cfg = $('Config').first().json;
const sale = $input.first().json;
const built = buildFlashSale(cfg, sale);
return [
  { json: { kind: 'video', payload: built.videoPayload, meta: built.meta }, pairedItem: { item: 0 } },
  { json: { kind: 'banner', payload: built.bannerPayload, meta: built.meta }, pairedItem: { item: 0 } },
];

// The free validate endpoint runs the exact pipeline a render submission
// runs, so a failure here is a payload bug - surface the field list for the
// deliverable that broke instead of a generic HTTP error. Runs once per
// item, so both the video and the banner are checked before either is paid
// for.
const built = $('Build project JSON').all();
return $input.all().map((res, i) => {
  const status = res.json.statusCode ?? (res.json.valid === true ? 200 : 400);
  const body = res.json.body || { ...res.json, details: res.json.errors ?? res.json.details };
  const kind = built[i].json.kind;
  if (status !== 200 || body.valid === false) {
    const details = Array.isArray(body.details)
      ? body.details.map((d) => '  - ' + d.field + ': ' + d.message).join('\n')
      : JSON.stringify(body).slice(0, 500);
    throw new Error('Zvid rejected the ' + kind + ' payload (HTTP ' + status + '): ' + (body.message || body.error) + '\n' + details);
  }
  return {
    json: { ...built[i].json, creditsRequired: body.creditsRequired, warnings: body.warnings || [] },
    pairedItem: { item: i },
  };
});

// Dry run: everything except the two paid renders. Open each editorLink to
// preview the exact video and the exact banner, then set dryRun to false in
// Config to render them for real. The sheet row is NOT marked done, so the
// next real run picks the same sale.
const cfg = $('Config').first().json;
const checked = $('Check validation').all();
const drafts = $input.all();
const total = checked.reduce((n, c) => n + (Number(c.json.creditsRequired) || 0), 0);

return checked.map((c, i) => {
  const d = c.json;
  // The draft save is best-effort (onError: continue) so a hiccup there never
  // hides the rest of the dry-run report.
  let editorLink = null;
  let draftId = null;
  const res = drafts[i] && drafts[i].json;
  const project = res && res.project;
  if (project && project.id) {
    draftId = project.id;
    editorLink = String(cfg.editorUrl || 'https://editor.zvid.io').replace(/\/+$/, '') + '/?project=' + project.id;
  }
  return {
    json: {
      dryRun: true,
      kind: d.kind,
      product: d.meta.product,
      oldPrice: d.meta.oldPrice,
      newPrice: d.meta.newPrice,
      discountPct: d.meta.discountPct,
      creditsRequired: d.creditsRequired,
      creditsForBothDeliverables: total,
      videoSeconds: d.meta.videoSeconds,
      bannerSize: d.meta.bannerSize,
      musicNote: d.meta.musicNote,
      editorLink,
      draftId,
      warnings: d.warnings,
      sheetUpdated: false,
      emailSent: false,
      nextStep: editorLink
        ? 'Open editorLink to preview this deliverable, then set dryRun to false in Config to render the video AND the banner for real.'
        : 'Set dryRun to false in Config to render this for real.',
      payload: d.payload,
    },
    pairedItem: { item: i },
  };
});

const response = $input.first().json;
const jobId = response.jobId || response.id;
if (!jobId) throw new Error('Render submission returned no jobId. Check https://app.zvid.io before retrying.');
const { payload, ...asset } = $('Prepare render attempt').first().json;
return [{ json: { ...asset, jobId, renderStartedAt: Date.now() }, pairedItem: { item: 0 } }];

const carried = $('Attach job to item').first().json;
const job = $input.first().json;
return [{ json: { ...carried, state: job.state, failedReason: job.failedReason || null, result: job.result || null }, pairedItem: { item: 0 } }];

const item = $input.first().json;
if (item.state === 'failed') throw new Error('The ' + item.kind + ' render failed: ' + (item.failedReason || 'no reason given'));
const timeoutMs = Number($('Config').first().json.timeoutMinutes || 20) * 60000;
if (Date.now() - Number(item.renderStartedAt) >= timeoutMs) {
  throw new Error('Render ' + item.jobId + ' timed out. It may still finish on Zvid; check https://app.zvid.io before retrying.');
}
return $input.all();

// Both jobs are finished by the time this runs: fold the two deliverables
// into ONE item so the sheet write-back, the email and the summary all see
// the same announcement, and build the email body here (a code node, where
// escaping is easy to get right) rather than inside an expression.
const cfg = $('Config').first().json;
const items = $input.all().map((i) => i.json);
const pick = (kind) => items.find((d) => d.kind === kind);
const urlOf = (d) => (d && (typeof d.result === 'string' ? d.result : (d.result ? d.result.url : null))) || null;

const video = pick('video');
const banner = pick('banner');
const videoUrl = urlOf(video);
const bannerUrl = urlOf(banner);
if (!videoUrl) throw new Error('The video render completed without returning a URL.');
if (!bannerUrl) throw new Error('The banner render completed without returning a URL.');

const meta = (video || banner).meta;
const credits = items.reduce((n, d) => n + (Number(d.creditsRequired) || 0), 0);

// Sheet / Shopify text is untrusted, so escape everything that lands in HTML.
const esc = (s) => String(s == null ? '' : s).replace(/[&<>"]/g, (c) => ({
  '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;',
}[c]));

const subjectTpl = String(cfg.emailSubject || 'Flash sale: {product} is {discount}% off');
const emailSubject = subjectTpl
  .replace(/\{product\}/g, meta.product)
  .replace(/\{discount\}/g, String(meta.discountPct))
  .replace(/\{oldPrice\}/g, meta.oldPrice)
  .replace(/\{newPrice\}/g, meta.newPrice)
  .replace(/\{brand\}/g, meta.brandName || '');

const storeLink = String(cfg.storeUrl || '').trim();
const href = storeLink ? (/^https?:/i.test(storeLink) ? storeLink : 'https://' + storeLink) : videoUrl;
const ink = String(cfg.inkColor || '#0D0D0D');
const accent = String(cfg.brandAccent || '#FFD54A');

const emailHtml =
  '<div style="font-family:Helvetica,Arial,sans-serif; background:' + ink + '; padding:28px; text-align:center;">' +
  '<a href="' + href + '"><img src="' + bannerUrl + '" alt="' + esc(meta.product) + ' flash sale" style="display:block; width:100%; max-width:600px; margin:0 auto; border:0;"/></a>' +
  '<p style="color:#FFFFFF; font-size:20px; font-weight:bold; margin:24px 0 6px;">' + esc(meta.product) + '</p>' +
  '<p style="color:#9CA3AF; font-size:15px; margin:0 0 22px;">' + esc(meta.oldPrice) + ' &rarr; ' + esc(meta.newPrice) + ' &middot; save ' + esc(meta.savedDisplay) + ' (' + meta.discountPct + '% off)' + (meta.endsAt ? ' &middot; ends ' + esc(meta.endsAt) : '') + '</p>' +
  '<a href="' + href + '" style="display:inline-block; background:' + accent + '; color:' + ink + '; font-weight:bold; padding:14px 34px; border-radius:999px; text-decoration:none;">' + esc(meta.ctaText) + '</a>' +
  '<p style="margin:26px 0 0;"><a href="' + videoUrl + '" style="color:#9CA3AF; font-size:13px;">Watch the 13-second sale video</a></p>' +
  '</div>';

return [{ json: {
  videoUrl,
  bannerUrl,
  product: meta.product,
  oldPrice: meta.oldPrice,
  newPrice: meta.newPrice,
  savedDisplay: meta.savedDisplay,
  discountPct: meta.discountPct,
  endsAt: meta.endsAt,
  bannerSize: meta.bannerSize,
  videoSeconds: meta.videoSeconds,
  musicNote: meta.musicNote,
  rowNumber: meta.rowNumber,
  sourceKind: meta.sourceKind,
  creditsCharged: credits,
  videoJobId: video ? video.jobId : null,
  bannerJobId: banner ? banner.jobId : null,
  emailSubject,
  emailHtml,
} }];

// Final report for a live run: ONE item carrying both URLs, so the two
// viewer nodes each download exactly one file.
const cfg = $('Config').first().json;
const d = $('Collect outputs').first().json;

let sheetUpdated = false;
try { $('Mark sale done').first(); sheetUpdated = true; } catch (e) { /* Shopify mode: no row to update */ }
let emailSent = false;
try { $('Email the banner').first(); emailSent = true; } catch (e) { /* email branch skipped */ }

return [{
  json: {
    rendered: true,
    product: d.product,
    oldPrice: d.oldPrice,
    newPrice: d.newPrice,
    discountPct: d.discountPct,
    endsAt: d.endsAt,
    videoUrl: d.videoUrl,
    bannerUrl: d.bannerUrl,
    videoSeconds: d.videoSeconds,
    bannerSize: d.bannerSize,
    creditsCharged: d.creditsCharged,
    videoJobId: d.videoJobId,
    bannerJobId: d.bannerJobId,
    musicNote: d.musicNote,
    source: cfg.source,
    sheetRow: d.rowNumber,
    sheetUpdated,
    sheetStatus: sheetUpdated ? cfg.statusDoneValue : null,
    emailSent,
    emailTo: emailSent ? cfg.emailTo : null,
  },
}];

// Each deliverable owns its retry deadline; an accepted job is never resubmitted.
return $input.all().map((item, i) => ({
  json: { ...item.json, submitStartedAt: Date.now(), submitAttempts: 0 },
  pairedItem: { item: i },
}));

// Retry only an explicit HTTP 429 rejection. Timeouts/5xx may have accepted
// a paid job already, so they stop for inspection instead of creating duplicates.
const item = $input.first();
const error = item.error || item.json.error || {};
const previous = $('Prepare render attempt').first().json;
const carried = item.json.payload ? item.json : previous;
const status = Number(error.httpCode || error.statusCode || error.response?.status || error.cause?.statusCode || error.cause?.response?.status);
// n8n's task-runner serialization drops httpCode but retains its exact,
// status-specific NodeApiError message and the API response in context.data.
const serialized429 = !status && error.name === 'NodeApiError' && error.message === 'The service is receiving too many requests from you';
if (status !== 429 && !serialized429) {
  throw new Error('Render submission failed: ' + (error.description || error.message || String(error)) + '. Check https://app.zvid.io before retrying; the request may already have created a job.');
}
let body = error.response?.data || error.context?.data || error.cause?.response?.data || error.cause?.error || {};
if (typeof body === 'string') { try { body = JSON.parse(body); } catch { body = {}; } }
const headers = error.response?.headers || error.cause?.response?.headers || {};
const rawRetry = headers['retry-after'] ?? body.retryAfter;
const retrySeconds = Number(rawRetry) || Math.ceil((Date.parse(rawRetry) - Date.now()) / 1000) || 30;
const waitSeconds = Math.max(30, retrySeconds);
const deadline = Number(previous.submitStartedAt) + Number($('Config').first().json.timeoutMinutes || 20) * 60000;
if (Date.now() + waitSeconds * 1000 >= deadline) {
  throw new Error('Render capacity stayed full until the submission deadline. Check https://app.zvid.io; completed assets from this run remain in Render one asset at a time.');
}
return [{ json: { ...carried, submitStartedAt: previous.submitStartedAt, submitAttempts: Number(carried.submitAttempts || 0) + 1, retrySeconds: waitSeconds }, pairedItem: { item: 0 } }];
